ok = 0
for path, (old, new) in replacements.items():
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()
    count = content.count(old)
    if count != 1:
        print(f"ATTENTION {path}: trouve {count} fois (attendu 1) - pas modifie")
        continue
    content = content.replace(old, new)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    ok += 1
    print(f"OK {path}")

print(f"\n{ok}/{len(replacements)} fichiers modifies")
